; ==============================================================
; Bank 7 ($07)  file offset $01C000-$01FFFF
; MULTI-TAB INFO SCREEN
; ==============================================================
;
; PURPOSE:
;   The OVERWORLD PARTY-MONSTER STATUS / INFO screen (a full-screen field
;   overlay, NOT battle-only).  Each of your party monsters gets one tab;
;   each tab has its own tile set copied into a different VRAM region:
;     tab 0 → VRAM $8500  (e.g. Stats page)
;     tab 1 → VRAM $8600  (e.g. Spells / Abilities page)
;     tab 2 → VRAM $8700  (e.g. Profile / description page)
;   $CA8D = number of party monsters = number of visible tabs (1..3);
;   the tabs indexed 0/1/2 correspond to the up-to-3 monsters in the party.
;
; WHEN IS THIS SHOWN? (the "bit1" situation)
;   bank6 fn6 ($6034) is the per-frame overworld router.  On the default
;   field path, its post-interaction tail ($6247) fires when the player
;   presses A ($C846 bit0) while facing NOTHING (the object scan found no
;   NPC/sign to talk to) AND a party exists ($CA8D != 0) AND nothing is
;   busy ($D8D7==0, $C8EB==0, $C850==0).  It then does:
;       SET $C8EB bit1  ($6269/$626C)   ; request the party-status overlay
;       $C90D..$C910 = 0                 ; reset THIS bank's state machine
;       SFX $59                          ; "open" sound
;   From the next frame, fn6's mode router ($6039, order 5,7,4,0,1,3,6,2)
;   sees bit1 set and bankcalls THIS function (bank7 fn0) every frame until
;   the screen closes.  Closing is fn0 state 4 ($69C1), which RES $C8EB bit1
;   and repaints the overworld — control returns to the normal field path.
;   In short: "press A on an empty tile in the field -> your party monster
;   status screen; press B/Select to close."
;
; MONSTER-SPRITE LOADING:
;   The tables at $6D40 (and neighbours) are {graphics-bank, tile-index}
;   lists that pull the monster's picture from the MONSTER-SPRITE GRAPHICS
;   banks $38/$39/$3A (bank56/57/58):
;     $6D40:  38 20 38 21 38 22 ...  = {bank $38, tile $20}, {bank $38, tile $21}, ...
;   i.e. this screen composes the on-screen monster from compressed sprite
;   blocks in banks $38-$3A. (Those banks: a 2-byte LE pointer table at
;   $4001 -> compressed 2bpp tiles. See bank56.asm.)
;
; WRAM LAYOUT (relevant addresses):
;   $C90D   current state index for fn0's RST $00 dispatch (0-4)
;   $CA4B   cursor / scroll X position  → HRAM[$FFD5]
;   $CA4C   cursor / scroll Y position  → HRAM[$FFD6]
;   $CA4D   cursor / scroll Z/layer     → HRAM[$FFD7]
;   $CA8D   party-monster count = number of visible tabs (1..3)
;   $CACA   scratch index passed to ROM0 $2619 (tile-select helper)
;   $C8DA   2-bit PAGE code (0..3): which info page of the current monster is
;           shown. bit0 toggled by Left/Right, bit1 by Up/Down (see state 2).
;           bit7 = "page changed" flag. State 3 dispatches on the low 2 bits.
;   $C92F   Start-toggle sub-mode flag (0/1); flips an alternate view + reloads
;           tab tiles (state 2, Start branch $43FD).
;   $C90D   fn0 outer state (0..4);  $C90E page-0 sub-step (0..15)
;
; FUNCTION TABLE (RST $10, H=$07):
;   fn0  $4009   main tick — reads $C90D state, dispatches via RST $00
;   fn1  $6313   [unknown — likely draw/refresh helper]
;   fn2  $6325   [unknown — likely input handler]
;   fn3  $562B   [unknown — likely init / open screen]
;   fn4  $0DFA   ROM0 routine (not a banked function)
;
; fn0 STATE MACHINE (WRAM[$C90D]) — driven every frame while $C8EB bit1 set:
;   state 0  ($696C)  INIT-A: clear $C8DA..$C8E1, load base tileset
;                     (bank$2E blk$0D -> VRAM $9000), build BG map, bank23 fn10,
;                     then INC $C90D -> state 1.
;   state 1  ($4017)  INIT-B: load tab tile sets for each party monster into
;                     VRAM $8500/$8600/$8700, draw tab headers, lay out BG map,
;                     then INC $C90D -> state 2.
;   state 2  ($43C8)  INPUT / NAVIGATION loop (redraws cursor each frame):
;                     Left/Right -> $C8DA ^= 1 ; Up/Down -> $C8DA ^= 2 (pick page)
;                     Start      -> $C92F ^= 1, rebuild tiles (alt view)
;                     A          -> SFX $59, INC $C90D -> state 3 (render page)
;                     B/Select   -> INC $C90D twice   -> state 4 (close)
;   state 3  ($44A8)  PAGE RENDER: RST$00 on $C8DA (4 pages). Page 0 ($44BE) is
;                     itself a 16-step sub-machine on $C90E (stats page build).
;   state 4  ($69C1)  CLOSE/TEARDOWN: RES $C8EB bit1, repaint overworld
;                     (bank1 fn3, bank11 fn1 tilemap + fn2 attrs, bank6 fn4),
;                     $C90D=0 -> back to the field.
;
; KEY SUBROUTINES (this bank):
;   $405C   load_tab_tiles — iterates tabs 0→1→2, copies source
;             tile data to VRAM $8500/$8600/$8700 via $656E
;   $43AB   [unknown — tile decompressor or blitter]
;   $656E   vram_copy — DMA or memcpy into VRAM
;   $67CA   [unknown — likely vblank wait / OAM update]
;   $694C   [unknown — called once on state 1 entry, likely clear]
;   $6799   [unknown — loads DE-pointed data; called twice in $402B]
;   $6B4C   [unknown]
;   $6C0B   [unknown — takes A=$C8DA value; layout related]
;
; RST $00 at $0000: state-dispatch (A=index, table follows instruction)
; ==============================================================
SECTION "bank7",ROMX[$4009],BANK[$07]


; Main tick for the multi-tab info screen.
;   Reads WRAM[$C90D] as a 0-4 state index and jumps via RST $00.
Bank7_fn0:  ; $4009
    LD A,($C90D)                           ; $4009 [FA 0D C9]  ; WRAM[$C90D]
    RST $00                                ; $400C [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (5 states):
    DW $696C    ; $400D [6C 69]  state 0 — INIT-A: clear vars, base tileset, ->1
    DW $4017    ; $400F [17 40]  state 1 — INIT-B: load tab tiles, layout, ->2
    DW $43C8    ; $4011 [C8 43]  state 2 — INPUT/NAV loop (A->3, B/Select->4)
    DW $44A8    ; $4013 [A8 44]  state 3 — PAGE RENDER (dispatch on $C8DA)
    DW $69C1    ; $4015 [C1 69]  state 4 — CLOSE: RES $C8EB.1, repaint overworld
; State 1: first frame setup.
;   Advances state to 2, loads cursor regs, copies tile data for active tabs.
.lbl_4017:
    LD HL,$C90D                            ; $4017 [21 0D C9]
    INC (HL)                               ; $401A [34]
    CALL $694C                             ; $401B [CD 4C 69]
    CALL $402B                             ; $401E [CD 2B 40]
    CALL $67CA                             ; $4021 [CD CA 67]
    CALL $405C                             ; $4024 [CD 5C 40]
    CALL $67CA                             ; $4027 [CD CA 67]
    RET                                    ; $402A [C9]
.lbl_402B:
    LD DE,$6EFA                            ; $402B [11 FA 6E]
    CALL $6799                             ; $402E [CD 99 67]
    LD DE,$6F3D                            ; $4031 [11 3D 6F]
    CALL $6799                             ; $4034 [CD 99 67]
    LD A,($CA4B)                           ; $4037 [FA 4B CA]  ; WRAM[$CA4B]
    LDH ($FFD5),A                          ; $403A [E0 D5]  ; → HRAM[$FFD5]
    LD A,($CA4C)                           ; $403C [FA 4C CA]  ; WRAM[$CA4C]
    LDH ($FFD6),A                          ; $403F [E0 D6]  ; → HRAM[$FFD6]
    LD A,($CA4D)                           ; $4041 [FA 4D CA]  ; WRAM[$CA4D]
    LDH ($FFD7),A                          ; $4044 [E0 D7]  ; → HRAM[$FFD7]
    LD HL,$002E                            ; $4046 [21 2E 00]
    CALL $673D                             ; $4049 [CD 3D 67]
    CALL $2388                             ; $404C [CD 88 23]  ; ROM0 $2388
    CALL $6B4C                             ; $404F [CD 4C 6B]
    LD DE,$44B4                            ; $4052 [11 B4 44]
    LD A,($C8DA)                           ; $4055 [FA DA C8]  ; WRAM[$C8DA]
    CALL $6C0B                             ; $4058 [CD 0B 6C]
    RET                                    ; $405B [C9]
; load_tab_tiles — copies tile graphics for each visible tab into VRAM.
;   Checks WRAM[$CA8D] (active tab) to decide how many sets to load:
;     tab 0 only  → source via $43AB → VRAM $8500
;     tab 0+1     → also VRAM $8600
;     tab 0+1+2   → also VRAM $8700
;   Each pass: set WRAM[$CACA] = tab index (via ROM0 $2619), then DMA.
.lbl_405C:
