; State 2 ($43C8) — INPUT HANDLER (per-frame while screen is open):
;   $C846 = newly-pressed buttons (bit0 A, b1 B, b2 Sel, b3 Start,
;   b4 R, b5 L, b6 U, b7 D). Reads it and reacts:
;     Left/Right ($30) → toggle bit0 of $C8DA (horizontal page select)
;     Up/Down   ($C0) → toggle bit1 of $C8DA (vertical page select)
;     Start     ($08) → toggle $C92F, clear sprite buffer $C5A0, reload
;                        tiles (via $405C) — switches display mode
;     B/Select  ($06) → advance state $C90D by 2 (begin close/exit)
;     A         ($01) → confirm/select (handled at $442C below)
;   $C8DA therefore holds the current page/tab as a 2-bit code.
; ---------------------------------------------------------------------------
; State 2 ($43C8) — INPUT / NAVIGATION loop (runs every frame; redraws cursor).
;   $C846 = newly-pressed buttons this frame (GB order: 0=A,1=B,2=Select,
;   3=Start,4=Right,5=Left,6=Up,7=Down). Priority: dpad-H, dpad-V, Start,
;   B/Select, A. Every branch falls through to $445C (redraw) then RET.
; ---------------------------------------------------------------------------
.lbl_43C8:
    CALL $4290                             ; $43C8 [CD 90 42]  ; refresh cursor/OAM
    LD HL,$C8DA                            ; $43CB [21 DA C8]  ; page code / flags
    RES 7,(HL)                             ; $43CE [CB BE]      ; clear "page changed" flag (bit7)
    LD A,($C846)                           ; $43D0 [FA 46 C8]  ; newly-pressed buttons
    AND $30                                ; $43D3 [E6 30]      ; --- Left|Right? (bits 4,5) ---
    JR Z,$43E1                             ; $43D5 [28 0A]      ; no H input -> check V
    LD A,($C8DA)                           ; $43D7 [FA DA C8]  ; page code
    XOR $01                                ; $43DA [EE 01]      ; toggle bit0 (flip page horizontally)
    LD ($C8DA),A                           ; $43DC [EA DA C8]  ; → page code
    JR,$43F0                               ; $43DF [18 0F]      ; -> page-changed
.lbl_43E1:
    LD A,($C846)                           ; $43E1 [FA 46 C8]  ; buttons
    AND $C0                                ; $43E4 [E6 C0]      ; --- Up|Down? (bits 6,7) ---
    JR Z,$43F6                             ; $43E6 [28 0E]      ; no V input -> check Start
    LD A,($C8DA)                           ; $43E8 [FA DA C8]  ; page code
    XOR $02                                ; $43EB [EE 02]      ; toggle bit1 (flip page vertically)
    LD ($C8DA),A                           ; $43ED [EA DA C8]  ; → page code
.lbl_43F0:                                 ;                    ; --- page changed (dpad) ---
    XOR A                                  ; $43F0 [AF]
    LD ($C914),A                           ; $43F1 [EA 14 C9]  ; reset page sub-step $C914=0
    JR,$445C                               ; $43F4 [18 66]      ; -> redraw
.lbl_43F6:
    LD A,($C846)                           ; $43F6 [FA 46 C8]  ; buttons
    AND $08                                ; $43F9 [E6 08]      ; --- Start? (bit3) ---
    JR Z,$441B                             ; $43FB [28 1E]      ; no Start -> check B/Select
    LD A,($C92F)                           ; $43FD [FA 2F C9]  ; alt-view flag
    XOR $01                                ; $4400 [EE 01]      ; toggle alt view
    LD ($C92F),A                           ; $4402 [EA 2F C9]  ; → alt-view flag
    LD HL,$C5A0                            ; $4405 [21 A0 C5]  ; clear tile-staging buffer $C5A0..
    LD BC,$0100                            ; $4408 [01 00 01]  ; 256 bytes
    LD A,$E0                               ; $440B [3E E0]     ; fill = $E0 (blank tile)
    CALL $169A                             ; $440D [CD 9A 16]  ; memset($C5A0,$E0,256)
    CALL $67CA                             ; $4410 [CD CA 67]  ; flush
    CALL $405C                             ; $4413 [CD 5C 40]  ; reload tab tiles for new view
    CALL $67CA                             ; $4416 [CD CA 67]  ; flush
    JR,$445C                               ; $4419 [18 41]      ; -> redraw
.lbl_441B:
    LD A,($C846)                           ; $441B [FA 46 C8]  ; buttons
    AND $06                                ; $441E [E6 06]      ; --- B|Select? (bits 1,2) = CLOSE ---
    JR Z,$442C                             ; $4420 [28 0A]      ; not B/Select -> check A
    LD HL,$C90D                            ; $4422 [21 0D C9]
    INC (HL)                               ; $4425 [34]         ; $C90D: 2 ->
    LD HL,$C90D                            ; $4426 [21 0D C9]
    INC (HL)                               ; $4429 [34]         ;        -> 4 (skip state 3, go to CLOSE)
    JR,$445C                               ; $442A [18 30]      ; -> redraw (last frame)
.lbl_442C:
    LD A,($C846)                           ; $442C [FA 46 C8]  ; buttons
    BIT 0,A                                ; $442F [CB 47]      ; --- A? (bit0) = enter/refresh page ---
    JR Z,$445C                             ; $4431 [28 29]      ; nothing pressed -> just redraw
    LD A,$59                               ; $4433 [3E 59]     ; SFX $59 ("select")
    CALL $1EFF                             ; $4435 [CD FF 1E]  ; ROM0 $1EFF (play SFX)
    LD HL,$C90D                            ; $4438 [21 0D C9]
    INC (HL)                               ; $443B [34]         ; $C90D: 2 -> 3 (render selected page)
    CALL $694C                             ; $443C [CD 4C 69]
    CALL $402B                             ; $443F [CD 2B 40]
    CALL $67CA                             ; $4442 [CD CA 67]
    XOR A                                  ; $4445 [AF]
    LD ($C90E),A                           ; $4446 [EA 0E C9]  ; → WRAM[$C90E]
    LD HL,$C8DA                            ; $4449 [21 DA C8]
    SET 7,(HL)                             ; $444C [CB FE]
    LD HL,$C8DB                            ; $444E [21 DB C8]
    LD BC,$0007                            ; $4451 [01 07 00]
    LD A,$00                               ; $4454 [3E 00]
    CALL $169A                             ; $4456 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    CALL $4469                             ; $4459 [CD 69 44]
.lbl_445C:
    LD DE,$44B4                            ; $445C [11 B4 44]
    LD A,($C8DA)                           ; $445F [FA DA C8]  ; WRAM[$C8DA]
    CALL $6B51                             ; $4462 [CD 51 6B]
    CALL $6636                             ; $4465 [CD 36 66]
    RET                                    ; $4468 [C9]
.lbl_4469:
