; State 3 ($44A8) — PAGE DISPATCHER (draw/run the selected page):
;   Reads the 2-bit page code $C8DA (set by the input handler in state 2)
;   and dispatches to one of 4 page handlers. Page 0 ($44BE) is itself a
;   16-step sub-machine keyed on $C90E; pages 1-3 live in banks of code
;   further down ($4A8A / $535B / $5B51).
.lbl_44A8:
    LD A,($C8DA)                           ; $44A8 [FA DA C8]  ; page code (0-3)
    RST $00                                ; $44AB [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (4 pages):
    DW $44BE    ; $44AC [BE 44]  page 0 — stats page (16-step sub-machine)
    DW $4A8A    ; $44AE [8A 4A]  page 1
    DW $535B    ; $44B0 [5B 53]  page 2
    DW $5B51    ; $44B2 [51 5B]  page 3
    ; --- DATA (not code): 5-word param block at $44B4 (used via $4052) ---
    DW $0021    ; $44B4 [21 00]
    DW $0026    ; $44B6 [26 00]
    DW $0061    ; $44B8 [61 00]
    DW $0066    ; $44BA [66 00]
    DW $FFFF    ; $44BC [FF FF]  end/sentinel
.lbl_44BE:
    LD A,($C90E)                           ; $44BE [FA 0E C9]  ; page-0 sub-step (0-15)
    RST $00                                ; $44C1 [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (16 sub-steps of page 0):
    DW $44E0    ; $44C2 [E0 44]  state 0
    DW $45FB    ; $44C4 [FB 45]  state 1
    DW $4655    ; $44C6 [55 46]  state 2
    DW $46AB    ; $44C8 [AB 46]  state 3
    DW $46B0    ; $44CA [B0 46]  state 4
    DW $46B9    ; $44CC [B9 46]  state 5
    DW $46CA    ; $44CE [CA 46]  state 6
    DW $47FE    ; $44D0 [FE 47]  state 7
    DW $4830    ; $44D2 [30 48]  state 8
    DW $48AB    ; $44D4 [AB 48]  state 9
    DW $48E6    ; $44D6 [E6 48]  state 10
    DW $4A12    ; $44D8 [12 4A]  state 11
    DW $4A5A    ; $44DA [5A 4A]  state 12
    DW $4A66    ; $44DC [66 4A]  state 13
    DW $4A78    ; $44DE [78 4A]  state 14
    DW $69CD    ; $44E0 [CD 69]  state 15
    LD B,H                                 ; $44E2 [44]
.lbl_44E3:
