; fn3 — 16-bit table lookup.
;   Input:  DE = index.
;   Output: DE = word at Bank7_fn3_table + 2*index  (table at $563A below).
;   Computes HL = $563A + 2*DE (ADD HL,HL doubles the index, then the
;   $3A/$56 add supplies the table base), reads the little-endian word.
;   The 224 entries are small numeric attributes shown on the info screen.
Bank7_fn3:  ; $562B
    LD L,E                                 ; $562B [6B]  ; HL = DE (index)
    LD H,D                                 ; $562C [62]
    ADD HL,HL                              ; $562D [29]  ; HL = index*2 (word stride)
    LD A,L                                 ; $562E [7D]
    ADD A,$3A                              ; $562F [C6 3A]  ; + low(table base $563A)
    LD L,A                                 ; $5631 [6F]
    LD A,H                                 ; $5632 [7C]
    ADC A,$56                              ; $5633 [CE 56]  ; + high(table base) w/ carry
    LD H,A                                 ; $5635 [67]  ; HL = &table[index]
    LD E,(HL)                              ; $5636 [5E]  ; DE = table[index] (lo)
    INC HL                                 ; $5637 [23]
    LD D,(HL)                              ; $5638 [56]  ; (hi)
    RET                                    ; $5639 [C9]
    ; --- DATA (not code): fn3 lookup table, 224 × 16-bit LE ---
    ;   Bank7_fn3 returns DE = table[index] where index is the
    ;   input in DE (see the ADD HL,HL; +$563A addressing above).
    ;   All values are small (<= $3E7), i.e. numeric attributes
    ;   used by the info screen — not code pointers.
Bank7_fn3_table:  ; $563A
    DW $0002,$0004,$000A,$0004,$0006,$000A,$0005,$0008  ; idx 0-7  ($563A)
    DW $000F,$0002,$0004,$0008,$0003,$0005,$000C,$0005  ; idx 8-15  ($564A)
    DW $000A,$000F,$0004,$0007,$0001,$0003,$0005,$0003  ; idx 16-23  ($565A)
    DW $0003,$0005,$0000,$0002,$0003,$0004,$0002,$0003  ; idx 24-31  ($566A)
    DW $0003,$0004,$0002,$0003,$0003,$0006,$0003,$0004  ; idx 32-39  ($567A)
    DW $0004,$0005,$0002,$0002,$0005,$0007,$0012,$0024  ; idx 40-47  ($568A)
    DW $000A,$0014,$03E7,$0002,$0002,$0002,$0002,$0002  ; idx 48-55  ($569A)
