; ---------------------------------------------------------------------------
; State 0 ($696C) — INIT-A (first frame after bank6 sets $C8EB bit1).
;   Clears the 8-byte state block $C8DA..$C8E1 (page code, flags, scratch),
;   computes the BG-map tile address for the cursor into $C911/$C912,
;   decompresses the base tileset (bank$2E blk$0D) to VRAM $9000, kicks
;   bank23 fn10, then INC $C90D so next frame runs state 1 (INIT-B).
; ---------------------------------------------------------------------------
.lbl_696C:
    LD HL,$C8DA                            ; $696C [21 DA C8]  ; page code / flags block base
    LD BC,$0008                            ; $696F [01 08 00]  ; 8 bytes: $C8DA..$C8E1
    LD A,$00                               ; $6972 [3E 00]
    CALL $169A                             ; $6974 [CD 9A 16]  ; memset($C8DA,0,8) — reset page/flags
.lbl_6977:
