    LD ($C911),A                           ; $699C [EA 11 C9]  ; → WRAM[$C911]
    LD A,H                                 ; $699F [7C]
    LD ($C912),A                           ; $69A0 [EA 12 C9]  ; → WRAM[$C912]
    CALL $694C                             ; $69A3 [CD 4C 69]
    CALL $67CA                             ; $69A6 [CD CA 67]
