    LD HL,$C90D                            ; $69BC [21 0D C9]  ; INIT-A done ->
    INC (HL)                               ; $69BF [34]         ; $C90D=1: next frame runs state 1 (INIT-B)
    RET                                    ; $69C0 [C9]
; ---------------------------------------------------------------------------
; State 4 ($69C1) — CLOSE / TEARDOWN (entered via B/Select in state 2).
;   Tears the status screen down and rebuilds the overworld it overlaid, then
;   clears $C8EB bit1 so bank6 fn6 resumes the normal field path next frame.
;   Tail ($69F3+, only if $C969!=0): reloads a few OBJ tiles (bank$2E blks
;   $15..) into VRAM $8500.. — restoring player/NPC sprite tiles the screen
;   had clobbered.
; ---------------------------------------------------------------------------
.lbl_69C1:
    CALL $694C                             ; $69C1 [CD 4C 69]  ; clear working buffer
    CALL $67CA                             ; $69C4 [CD CA 67]  ; flush / vblank
    LD HL,$170A                            ; $69C7 [21 0A 17]
    RST $10                                ; $69CA [D7]  ; bankcall → bank23 fn10
    LD HL,$0103                            ; $69CB [21 03 01]
    RST $10                                ; $69CE [D7]  ; bankcall → bank1 fn3 (restore field state)
    LD HL,$0B01                            ; $69CF [21 01 0B]
    RST $10                                ; $69D2 [D7]  ; bankcall → bank11 fn1 (repaint tilemap $9800)
    LD HL,$0B02                            ; $69D3 [21 02 0B]
