; ============================================================================
; MONSTER-SPRITE LOOKUP TABLE  $6CC2..$6E90  (231 entries x 2 bytes)
; ============================================================================
; {graphics-bank, block-index} per sprite slot -> composes the on-screen
; monster picture. bank byte: $38-$3A = info-screen sprite banks
; (tiles/bank56-58); $2F-$37 = battle-sprite banks. block = index into that
; bank's $4001 pointer table (the compressed sprite block).
; NB: this was force-DISASSEMBLED AS CODE (bogus JR C/LD runs); restored as
; the data table it is. Read by fn0 via the $6D40 region (header note).
;
; INDEX semantics NOT yet confirmed (no immediate base-load found; access is
; computed/indirect). Evidence it is NOT a simple index==species table:
;   - entries [1..14] are all identical {$31,$40} (placeholders/reserved),
;   - entries [16+] are a plain SEQUENTIAL {bank,block} enumeration
;     ($2F blk $02-$10, then $38 blk $01.., into $39/$3A).
; So do NOT assume entry N == species N. The $38-$3A run is the info-screen
; monster-sprite set in order; the true index->species map needs the reader.
; ============================================================================
Bank7_SpriteTable:                          ; $6CC2
    DB $2F,$40   ; $6CC2  [  0] {bank $2F, block $40}  battle-sprite bank
    DB $31,$40   ; $6CC4  [  1] {bank $31, block $40}  battle-sprite bank
